(()=>{'use strict';
const D=window.STUDY,mods=D.modules,lessons=D.lessons,essays=D.essay,authors=D.authors;
const LS='apexhub_csc426_studio_v1';const $=s=>document.querySelector(s);const html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let store;try{store=JSON.parse(localStorage.getItem(LS)||'{}')}catch{store={}};
store={complete:[],attempts:[],stats:{},notes:{},lastPrompt:Date.now(),created:Date.now(),...store};
const save=()=>{try{localStorage.setItem(LS,JSON.stringify(store))}catch{}};
let currentLesson=null,miniAnswer=null,quiz=null,quizResult=null,vaultFilter='all',vaultSearch='',authorFlips=new Set(),focusTimer=null,focusSeconds=25*60,focusRunning=false,voiceRate=1;
const now=()=>Date.now(),modName=id=>mods.find(m=>m.id===id)?.title||'All topics';const modLessons=id=>lessons.filter(x=>x.module===id);
const videos=[
{id:'software-engineering',title:'Software Engineering and Named Authors',module:'intro',duration:'54 sec',summary:'The full lifecycle, Pfleeger, Philips and IEEE.'},
{id:'elicitation-fishbone',title:'Elicitation and Ishikawa Fishbone',module:'elicitation',duration:'48 sec',summary:'Discover stakeholder needs and draw the cause-and-effect diagram.'},
{id:'requirements-feasibility',title:'DIPM, Requirements and TELOS',module:'analysis',duration:'50 sec',summary:'Clarify raw requirements and decide project feasibility.'},
{id:'development-models',title:'Development Models Explained',module:'sdlc',duration:'47 sec',summary:'Waterfall, V, Evolutionary, Agile and Spiral compared.'},
{id:'implementation-conversion',title:'Implementation and Four Conversion Strategies',module:'implementation',duration:'48 sec',summary:'Migrating, launching and changing systems safely.'},
{id:'software-testing',title:'Software Testing and V&V',module:'testing',duration:'54 sec',summary:'Testing levels, techniques, load, stress and regression.'}
];
const videoFor=module=>videos.find(x=>x.module===module||(module==='feasibility'&&x.id==='requirements-feasibility'));
const allMCQ=[...lessons.map(l=>({id:l.id,module:l.module,...l.check,lessonId:l.id})),...D.extras];const allEssay=essays.map(e=>({...e,type:'essay'}));
const completeCount=()=>store.complete.length;const pct=n=>Math.round(n/lessons.length*100);const getStats=id=>store.stats[id]||{right:0,wrong:0,streak:0,nextDue:0};
const attemptsFor=id=>store.attempts.filter(x=>x.id===id);const wrongCount=()=>Object.values(store.stats).filter(x=>x.wrong>0&&x.right<=x.wrong).length;
function toast(message){const e=$('#toast');e.textContent=message;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),3300)}
function record(q,correct,mode,reply=''){const s=getStats(q.id);s[correct?'right':'wrong']++;s.streak=correct?s.streak+1:0;s.nextDue=now()+(correct?Math.min(90,3*Math.pow(2,Math.min(s.streak,5))):2)*60e3;store.stats[q.id]=s;store.attempts.push({id:q.id,topic:q.module,question:q.prompt,correct,mode,reply,at:new Date().toISOString()});save()}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function navigate(hash){location.hash='#'+hash;route();window.scrollTo({top:0,behavior:'instant'});$('#sidebar').classList.remove('open')}
function route(){const full=decodeURIComponent(location.hash.replace(/^#/,'')||'home');const [page,param]=full.split('/');renderNav(page,param);let view='';if(page==='lesson')view=renderLesson(param);else if(page==='module')view=renderModule(param);else if(page==='authors')view=renderAuthors();else if(page==='videos')view=renderVideos();else if(page==='quiz')view=renderQuiz();else if(page==='vault')view=renderVault();else if(page==='plan')view=renderPlan();else if(page==='mock')view=renderMockStart();else view=renderHome();$('#view').innerHTML=view;$('#view').focus({preventScroll:true});renderPrompt();refreshClock()}
function renderNav(page,param){let out='<div class="nav-title">STUDY DESK</div>';
const base=[['home','⌂','Overview'],['authors','♟','Author memory arena'],['videos','▷','Video explainers'],['quiz','⚡','Practice lab'],['mock','◷','Timed mock exam'],['vault','▤','Question vault'],['plan','◫','Revision plan']];
for(const [id,icon,text]of base)out+=`<button class="navlink ${id===page||id==='home'&&page==='home'?'active':''}" data-action="navigate" data-target="${id}"><span>${icon}</span>${text}</button>`;
out+='<div class="nav-title">THE SEVEN CHAPTERS</div>';
for(let i=0;i<mods.length;i++){let m=mods[i],num=modLessons(m.id).filter(x=>store.complete.includes(x.id)).length;out+=`<button class="navlink ${param===m.id||page==='lesson'&&lessons.find(l=>l.id===param)?.module===m.id?'active':''}" data-action="navigate" data-target="module/${m.id}"><span>${String(i+1).padStart(2,'0')}</span><span style="flex:1">${html(m.title)}</span><span class="nav-count">${num}/${modLessons(m.id).length}</span></button>`}$('#nav').innerHTML=out;
$('#sideProgress').innerHTML=`<b style="color:#fff">Your preparation</b><p>${completeCount()} of ${lessons.length} lessons completed</p><div class="bar"><i style="width:${pct(completeCount())}%"></i></div><p>Offline lessons · progress on this device</p>`;
let label=page==='lesson'?lessons.find(x=>x.id===param)?.title:page==='module'?modName(param):{home:'Your learning desk',authors:'Author memory arena',videos:'Video explanations',quiz:'Practice laboratory',mock:'Timed mock exam',vault:'Complete question vault',plan:'Revision plan'}[page];$('#breadcrumb').textContent=label||'CSC426 Exam Studio';}
function countdown(){const v=new Date(D.meta.deadline).getTime()-now();if(v<=0)return '00:00:00';const h=Math.floor(v/36e5),m=Math.floor((v%36e5)/6e4),s=Math.floor((v%6e4)/1000);return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function refreshClock(){document.querySelectorAll('[data-countdown]').forEach(e=>e.textContent=countdown());$('#topClock').textContent=new Intl.DateTimeFormat('en-NG',{timeZone:'Africa/Lagos',hour:'2-digit',minute:'2-digit',hour12:true}).format(new Date())+' WAT';const t=$('[data-quiztimer]');if(t&&quiz?.mode==='mock'){let remain=Math.max(0,quiz.endTime-now());t.textContent=`${String(Math.floor(remain/60000)).padStart(2,'0')}:${String(Math.floor(remain%60000/1000)).padStart(2,'0')}`;if(!remain&&quiz&& !quiz.ended){endQuiz()}}if(focusRunning&&focusTimer){const timer=$('[data-focusclock]');if(timer)timer.textContent=formatSeconds(focusSeconds)}}
const formatSeconds=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
function renderHome(){let last=lessons.find(l=>!store.complete.includes(l.id))||lessons[0],due=allMCQ.filter(q=>getStats(q.id).wrong>0&&getStats(q.id).nextDue<=now()).length;
return `<section class="hero"><div><span class="eyebrow">A better way to learn software engineering</span><h1>Understand it. Remember it. Explain it.</h1><p>Every definition stays intact. Learn with campus examples, visual explainers, narration, author recall and repeated questions.</p><div class="actions"><button class="btn" data-action="navigate" data-target="lesson/${last.id}">Continue learning →</button><button class="btn secondary" data-action="start-quiz" data-mode="adaptive">Start recall practice</button><button class="btn secondary" data-action="navigate" data-target="videos">Watch explainers ▷</button></div></div><div class="countdown"><small>UNTIL SAT, 14 NOV · 7:00 AM WAT</small><strong data-countdown>${countdown()}</strong><small>Study deadline</small></div></section>
<div class="metrics"><div class="metric"><strong>${completeCount()} / ${lessons.length}</strong><span>Lessons complete</span></div><div class="metric"><strong>${Object.keys(store.stats).length}</strong><span>Questions practised</span></div><div class="metric"><strong>${wrongCount()}</strong><span>Weak topics to revisit</span></div><div class="metric"><strong>${due}</strong><span>Questions ready to repeat</span></div></div>
<div class="section-head"><h2>The complete course</h2><span class="small">7 chapters · ${lessons.length} focused lessons</span></div>${moduleCards()}
<div class="section-head"><h2>Watch, then practise</h2><button class="btn secondary small" data-action="navigate" data-target="videos">See all 6 videos →</button></div><div class="panel"><div class="flex" style="justify-content:space-between"><div><b>Six original narrated video explainers</b><p class="muted">Short diagrams and spoken lessons you can play offline, then test your recall.</p></div><button class="btn soft" data-action="navigate" data-target="videos">Open video studio →</button></div></div><div class="section-head"><h2>Train your memory</h2></div><div class="two-col"><div class="panel"><span class="eyebrow">Author recall</span><h3 style="margin:7px 0">Who said what, and when?</h3><p class="muted">Seven named people, organisations and events, including Pfleeger, Philips, IEEE, Ishikawa, Munassan and Pressman.</p><div class="actions"><button class="btn soft" data-action="navigate" data-target="authors">Open author arena →</button></div></div><div class="panel"><span class="eyebrow">Exam readiness</span><h3 style="margin:7px 0">Don't just reread. Retrieve.</h3><p class="muted">${allMCQ.length} multiple-choice checks and ${allEssay.length} exam-style written questions. Review missed answers and practise again.</p><div class="actions"><button class="btn soft" data-action="navigate" data-target="vault">Browse question vault →</button></div></div></div><div class="section-head"><h2>Printable revision pack</h2></div><div class="panel"><div class="actions"><a class="btn secondary" href="CSC426_Complete_Study_Notes.pdf" download>↓ Complete notes · 41 pages</a><a class="btn secondary" href="CSC426_Complete_Question_Bank.pdf" download>↓ Questions + answers · 34 pages</a><a class="btn secondary" href="CSC426_Author_Memory_Sheet.pdf" download>↓ One-page author sheet</a></div></div>`}
function moduleCards(){return `<div class="module-grid">${mods.map((m,i)=>{let items=modLessons(m.id),n=items.filter(x=>store.complete.includes(x.id)).length;return `<article class="module-card"><div class="module-top"><div class="numberbox">${String(i+1).padStart(2,'0')}</div><div><h3>${html(m.title)}</h3><p>${html(m.subtitle)}</p></div></div><div class="bar"><i style="width:${Math.round(n/items.length*100)}%"></i></div><div class="bottom"><span>${n} of ${items.length} lessons completed</span><button class="btn secondary small" data-action="navigate" data-target="module/${m.id}">Open chapter →</button></div></article>`}).join('')}</div>`}
function renderModule(id){const m=mods.find(x=>x.id===id);if(!m)return renderHome();const items=modLessons(id),n=items.filter(x=>store.complete.includes(x.id)).length;return `<div class="title-block"><div><span class="eyebrow">CHAPTER ${mods.indexOf(m)+1} / 7</span><h1>${html(m.title)}</h1><p>${html(m.subtitle)}. ${n} of ${items.length} lessons completed.</p></div><button class="btn" data-action="navigate" data-target="lesson/${(items.find(x=>!store.complete.includes(x.id))||items[0]).id}">${n?'Continue chapter':'Start chapter'} →</button></div><div class="panel"><div class="flex" style="justify-content:space-between"><b>Chapter progress</b><b>${Math.round(100*n/items.length)}%</b></div><div class="bar" style="margin-top:10px"><i style="width:${Math.round(100*n/items.length)}%"></i></div></div><div class="section-head"><h2>Lessons and definitions</h2><button class="btn secondary small" data-action="start-quiz" data-mode="module" data-module="${id}">Quiz this chapter</button></div><div class="module-grid">${items.map((l,i)=>`<article class="module-card"><div class="module-top"><div class="numberbox">${store.complete.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</div><div><h3>${html(l.title)}</h3><p>${l.author?html(l.author)+' · ':''}${html(l.source)}</p></div></div><div class="bottom"><span>${store.complete.includes(l.id)?'Studied':'Ready to learn'}</span><button class="btn secondary small" data-action="navigate" data-target="lesson/${l.id}">${store.complete.includes(l.id)?'Review':'Study'} →</button></div></article>`).join('')}</div>`}
function renderLesson(id){const l=lessons.find(x=>x.id===id);if(!l)return renderHome();currentLesson=l.id;miniAnswer=null;const idx=lessons.indexOf(l),prev=lessons[idx-1],next=lessons[idx+1];let related=modLessons(l.module);return `<div class="lesson-head"><div><span class="eyebrow">${html(modName(l.module))} · Lesson ${related.indexOf(l)+1}/${related.length}</span><h1>${html(l.title)}</h1><span class="tag">Source material kept in full</span> ${l.author?`<span class="tag plain">${html(l.author)}</span>`:''}</div><div class="actions"><button class="btn secondary small" data-action="navigate" data-target="${prev?'lesson/'+prev.id:'module/'+l.module}">← Previous</button><button class="btn secondary small" data-action="navigate" data-target="${next?'lesson/'+next.id:'module/'+l.module}">Next →</button></div></div><div class="lesson-layout"><div class="lesson-main">
<section class="panel"><span class="eyebrow">01 · Full academic definition</span><div class="quote">${html(l.academic)}</div><div class="flex" style="justify-content:space-between;margin-top:13px"><span class="small">Source: ${html(l.source)}</span><div class="actions" style="margin:0"><button class="btn secondary small" data-action="speak" data-part="academic">▶ Listen</button><button class="btn secondary small" data-action="stop-voice">■ Stop</button></div></div></section>
<section class="panel"><span class="eyebrow">02 · Understand in plain English</span><p style="font-size:16px;margin-top:10px">${html(l.simple)}</p><div class="scenario" style="margin-top:14px"><b>REAL-LIFE SCENARIO</b><p>${html(l.example)}</p></div><div class="actions"><button class="btn soft small" data-action="speak" data-part="all">▶ Narrate full lesson</button><span class="small">Voice available when supported by browser</span></div></section>
<section class="panel"><span class="eyebrow">03 · See the concept</span><h3 style="margin:7px 0 12px">Visual explanation</h3>${visualFor(l)}<div class="actions" style="margin-top:13px"><button class="btn soft small" data-action="navigate" data-target="videos">▷ Watch related chapter explainer</button></div></section>
<section class="panel"><span class="eyebrow">04 · Important points to reproduce</span><ul class="keylist">${l.keys.map(x=>`<li>${html(x)}</li>`).join('')}</ul><div class="memory" style="margin-top:15px"><b>MEMORY ANCHOR</b><p>${html(l.memory)}</p></div>${l.extra?`<div class="feedback" style="margin-top:14px"><b>Source-context note:</b> ${html(l.extra)}</div>`:''}</section>
<section class="panel"><span class="eyebrow">05 · Recall before moving on</span><h3 style="margin-top:9px">${html(l.check.prompt)}</h3><div id="miniBox">${miniOptions(l)}</div></section>
<section class="panel"><span class="eyebrow">06 · Explain it yourself</span><p class="muted">Without looking above, write how you would explain this to a classmate. This is your private revision note.</p><textarea class="notes-input" id="lessonNotes" placeholder="Write your own explanation or mnemonic here...">${html(store.notes[l.id]||'')}</textarea><div class="actions"><button class="btn secondary small" data-action="save-notes">Save notes</button><button class="btn" data-action="complete-lesson">${store.complete.includes(l.id)?'✓ Reviewed · Continue':'Mark studied · Continue →'}</button></div></section></div>
<aside class="lesson-side"><div class="panel"><b>Chapter lessons</b><div class="lesson-toc">${related.map((x,i)=>`<button class="${x.id===l.id?'active':''} ${store.complete.includes(x.id)?'done':''}" data-action="navigate" data-target="lesson/${x.id}">${i+1}. ${html(x.title)}</button>`).join('')}</div></div></aside></div>`}
function miniOptions(l){const prev=miniAnswer?.id===l.id?miniAnswer:null;return `${l.check.choices.map((opt,i)=>`<button class="option ${prev&&i===l.check.answer?'correct':''} ${prev&&prev.choice===i&&i!==l.check.answer?'wrong':''}" ${prev?'disabled':''} data-action="mini" data-index="${i}" data-id="${l.id}"><span class="letter">${'ABCD'[i]}.</span><span>${html(opt)}</span></button>`).join('')}${prev?`<div class="feedback ${prev.choice===l.check.answer?'good':'bad'}"><b>${prev.choice===l.check.answer?'Correct!':'Review this.'}</b> ${html(l.check.explanation)}</div>`:''}`}
function flowBox(labels){return `<div class="flow">${labels.map((s,i)=>`${i?'<span class="flow-arrow">→</span>':''}<div class="flow-step" data-flow-step="${i}">${html(s)}</div>`).join('')}</div>`}
function svg(content,h=230){return `<svg viewBox="0 0 660 ${h}" role="img" aria-label="Animated diagram explaining the concept">${content}</svg>`}
function rect(x,y,w,h,text,hot=false){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${hot?'#3268ee':'var(--surf)'}" stroke="${hot?'#3268ee':'#8ba7e4'}" stroke-width="2"/><text x="${x+w/2}" y="${y+h/2+5}" text-anchor="middle" font-size="13" font-weight="bold" fill="${hot?'white':'var(--text)'}">${html(text)}</text>`}
const arrow=(x1,y1,x2,y2)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#6f91d8" stroke-width="2.5" marker-end="url(#ar)"/>`;
function defs(){return `<defs><marker id="ar" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6Z" fill="#6f91d8"/></marker></defs>`}
function visualFor(l){const typ=l.visual;let graphic='',label='Follow the highlighted steps and describe what happens';
if(typ==='fish'){label='Head = late results; four cause groups = fish bones. Course exam guidance prefers an even count.';graphic=svg(`${defs()}<line x1="80" y1="115" x2="525" y2="115" stroke="#658bd8" stroke-width="5"/>${arrow(500,115,566,115)}<polygon points="560,115 528,82 528,148" fill="#3268ee"/><text x="552" y="109" font-size="12" font-weight="bold" fill="white">Late</text><text x="548" y="123" font-size="12" font-weight="bold" fill="white">results</text><path d="M170 115L110 40 M285 115L235 40 M360 115L420 40 M450 115L495 175" stroke="#658bd8" stroke-width="3"/>${[['Students',60,30],['Lecturers',195,30],['ICT',412,30],['Registry',482,194]].map(a=>`<text x="${a[1]}" y="${a[2]}" font-size="14" font-weight="bold" fill="var(--text)">${a[0]}</text>`).join('')}<text x="90" y="146" fill="var(--muted)" font-size="11">Potential causes are investigated, not automatically assumed.</text>`,235)}
else if(typ==='vmodel'){label='The left side designs and verifies, the base codes, and the right side tests.';graphic=svg(`${defs()}<path d="M110 46L330 195L550 46" fill="none" stroke="#427aff" stroke-width="4"/>${rect(15,16,170,39,'Requirements')}${rect(475,16,170,39,'Acceptance tests')}${rect(100,70,165,39,'Architecture')}${rect(395,70,170,39,'System tests')}${rect(175,124,145,39,'Detailed design')}${rect(342,124,150,39,'Integration tests')}${rect(256,183,146,39,'Coding',true)}<text x="23" y="221" fill="var(--muted)" font-size="11">VERIFICATION ↘</text><text x="515" y="221" fill="var(--muted)" font-size="11">↗ VALIDATION</text>`,246)}
else if(typ==='waterfall'){let steps=['Requirements','System design','Program design','Code + unit test','Integration test','Maintenance'];graphic=svg(`${defs()}${steps.map((s,i)=>rect(25+i*76,15+i*33,150,38,s,i===3)+(i<5?arrow(118+i*76,55+i*33,122+(i+1)*76,17+(i+1)*33):'')).join('')}`,255);label='Sequential stages descend like stairs; late changes can be expensive.'}
else if(typ==='pyramid'){graphic=svg(`<polygon points="270,28 390,28 450,80 210,80" fill="#376dff"/><polygon points="210,84 450,84 520,139 140,139" fill="#5d88ef"/><polygon points="140,143 520,143 580,194 80,194" fill="#81a5f0"/><polygon points="80,198 580,198 627,231 33,231" fill="#bed0f4"/><text x="330" y="59" text-anchor="middle" font-size="16" fill="white" font-weight="bold">Acceptance</text><text x="330" y="119" text-anchor="middle" font-size="16" fill="white" font-weight="bold">System</text><text x="330" y="176" text-anchor="middle" font-size="16" fill="#15264c" font-weight="bold">Integration</text><text x="330" y="221" text-anchor="middle" font-size="16" fill="#15264c" font-weight="bold">Unit</text>`,255);label='From individual modules up to client acceptance of the complete system.'}
else if(typ==='spiral'){let coils='<path d="M325 125 C370 105 370 155 327 155 C275 155 265 85 345 73 C450 58 480 180 343 201 C205 218 173 57 320 35" fill="none" stroke="#376dff" stroke-width="4" stroke-linecap="round"/>';graphic=svg(`${defs()}${coils}${rect(24,25,150,36,'Plan')}${rect(464,25,175,36,'Analyse risk')}${rect(20,185,165,36,'Evaluate')}${rect(480,185,160,36,'Develop')}<text x="329" y="135" text-anchor="middle" font-size="12" fill="var(--muted)">Repeat cycles</text>`);label='Every loop revisits planning, risk analysis, development and evaluation.'}
else if(typ==='blackbox'){graphic=svg(`${defs()}${rect(12,84,152,65,'INPUT')}${rect(242,63,170,105,'SYSTEM',true)}${rect(492,84,152,65,'OUTPUT')}${arrow(168,116,237,116)}${arrow(416,116,486,116)}<text x="327" y="126" text-anchor="middle" font-size="13" fill="white">${l.title.startsWith('White')?'CODE VISIBLE':l.title.startsWith('Grey')?'PARTLY VISIBLE':'CODE HIDDEN'}</text><text x="330" y="201" text-anchor="middle" font-size="13" fill="var(--text)">Test inputs and compare expected and actual outcomes</text>`);label=l.title.startsWith('White')?'Inspect conditions and branches inside the code.':l.title.startsWith('Grey')?'Use partial internal knowledge alongside external behaviour.':'Test inputs and outputs without inspecting code.'}
else if(typ==='chart'){graphic=svg(`${defs()}<line x1="70" y1="192" x2="602" y2="192" stroke="#aab6d4" stroke-width="2"/><line x1="70" y1="20" x2="70" y2="193" stroke="#aab6d4" stroke-width="2"/><path d="M72 180 Q180 173 280 150 Q390 113 444 111 Q530 120 592 186" stroke="#3a73fd" stroke-width="5" fill="none"/><line x1="442" y1="28" x2="442" y2="193" stroke="#d48b3a" stroke-width="2" stroke-dasharray="5,5"/><text x="325" y="222" text-anchor="middle" font-size="12" fill="var(--muted)">Increasing users / workload →</text><text x="12" y="20" font-size="12" fill="var(--muted)">Response</text><text x="12" y="34" font-size="12" fill="var(--muted)">quality</text><text x="245" y="113" font-size="14" fill="var(--blue)">Normal load</text><text x="457" y="55" font-size="14" fill="#bd7b31">Stress zone</text>`);label='Conceptual illustration only: normal expected load versus overload beyond capacity.'}
else if(typ==='conversion'){graphic=svg(`${defs()}${['Direct: old → STOP → new','Parallel: old + new together','Pilot: one branch, then all','Phased: module by module'].map((x,i)=>rect(35,15+i*57,590,44,x,i===1)).join('')}`,258);label='Four conversion strategies differ in when, where and how much is replaced.'}
else if(typ==='data'){graphic=flowBox(['Extract','Clean','Validate','Transform','Load','Verify']);label='Quality checking and reconciliation are essential before relying on migrated data.'}
else if(typ==='timeline'){graphic=svg(`${defs()}${arrow(60,137,608,137)}<circle cx="180" cy="137" r="14" fill="#376dff"/><circle cx="437" cy="137" r="14" fill="#376dff"/><text x="180" y="101" text-anchor="middle" font-size="23" font-weight="bold" fill="var(--text)">1968</text><text x="180" y="171" text-anchor="middle" font-size="13" fill="var(--muted)">Software crisis</text><text x="437" y="101" text-anchor="middle" font-size="23" font-weight="bold" fill="var(--text)">Today</text><text x="437" y="171" text-anchor="middle" font-size="13" fill="var(--muted)">Disciplined delivery</text>`);label='The crisis motivated more rigorous software engineering practices.'}
else if(typ==='compare'){graphic=svg(`${defs()}${rect(22,25,290,55,l.title.includes('Validation')||l.title.includes('Verification')?'Verification':'WHAT / INPUT')}${rect(348,25,290,55,l.title.includes('Validation')||l.title.includes('Verification')?'Validation':'HOW / OUTPUT',true)}${rect(22,103,290,64,'Specification / structure')}${rect(348,103,290,64,'Real needs / behaviour',true)}${arrow(317,128,345,128)}<text x="330" y="210" text-anchor="middle" fill="var(--muted)" font-size="12">Differentiate purpose, timing and evidence</text>`);label='Compare both sides by purpose, input, output and example.'}
else if(typ==='iterations'){graphic=svg(`${defs()}${['Version 1','Feedback','Version 2','Feedback','Final'].map((x,i)=>rect(18+i*130,80,114,55,x,i===4)+(i<4?arrow(132+i*130,106,147+i*130,106):'')).join('')}<path d="M547 155 Q330 231 98 154" stroke="#8da9dc" fill="none" stroke-width="2" stroke-dasharray="6"/><text x="332" y="208" text-anchor="middle" fill="var(--muted)" font-size="12">Iterate, learn and improve</text>`);label='Small usable releases are improved through repeated feedback.'}
else if(typ==='cycle'){graphic=svg(`${defs()}${rect(255,12,150,47,'Plan')}${rect(475,100,160,47,'Build')}${rect(255,183,150,47,'Test')}${rect(22,100,155,47,'Improve')}${arrow(411,39,491,94)}${arrow(549,150,412,194)}${arrow(250,206,168,152)}${arrow(110,93,248,44)}`);label='The lifecycle includes feedback and maintenance, not just initial coding.'}
else if(typ==='cards'){const k=l.keys.slice(0,4).map(x=>x.length>19?x.slice(0,17)+'…':x);graphic=svg(`${defs()}${k.map((x,i)=>rect(18+i*161,57,145,113,x,i===1)).join('')}`,235);label='Break a larger definition into a small number of memorable ideas.'}
else{let things=(l.memory.includes('DIPM')?['Detect','Identify','Prioritize','Model']:l.title.includes('Interview')?['Prepare','Introduce','Ask & probe','Review']:l.title.includes('Data')?['Extract','Clean','Transform','Load']:l.title.includes('System Development')?['Design','Develop','Integrate','Deploy']:l.title.includes('TELOS')?['Technical','Economic','Legal','Operational','Schedule']:['Understand','Build','Check','Improve']);graphic=flowBox(things)}
return `<div class="visual" id="visual-${l.id}">${graphic}<div class="visual-note">${html(label)}</div></div><div class="actions" style="margin-top:10px"><button class="btn secondary small" data-action="replay-visual">↻ Replay explanation</button><button class="btn soft small" data-action="speak" data-part="visual">▶ Hear example</button></div>`}
function renderVideos(){return `<div class="title-block"><div><span class="eyebrow">Original narrated lessons / offline videos</span><h1>Watch it happen</h1><p>Six short explainer videos with spoken narration and illustrated examples. Pause, replay and answer the chapter quiz after each clip.</p></div><span class="tag">6 original videos · approx 5 minutes total</span></div><div class="module-grid">${videos.map((v,i)=>`<div class="panel"><div class="flex" style="justify-content:space-between"><span class="eyebrow">EXPLAINER ${String(i+1).padStart(2,'0')}</span><span class="tag plain">${v.duration}</span></div><h3 style="margin:9px 0">${html(v.title)}</h3><p class="muted" style="min-height:37px">${html(v.summary)}</p><video controls playsinline preload="metadata" poster="videos/${v.id}.jpg" style="width:100%;margin:11px 0;border-radius:11px;background:#091a38;aspect-ratio:16/9" aria-label="${html(v.title)}"><source src="videos/${v.id}.mp4" type="video/mp4">Your browser cannot play MP4 video. The narrated definitions and interactive visual lessons are still available.</video><div class="actions" style="margin-top:3px"><button class="btn soft small" data-action="navigate" data-target="module/${v.module}">Study chapter →</button><button class="btn secondary small" data-action="start-quiz" data-mode="module" data-module="${v.module}">Quiz what you watched</button></div></div>`).join('')}</div><div class="panel" style="margin-top:17px"><b>Learning technique</b><p class="muted">Watch a video once, close it, try to explain the concept aloud, then attempt the chapter quiz. Text definitions remain available in the 61 full lessons and in the downloadable PDF.</p><div class="actions"><a class="btn secondary small" href="CSC426_Complete_Study_Notes.pdf" download>↓ Complete notes PDF</a></div></div>`}
function renderAuthors(){return `<div class="title-block"><div><span class="eyebrow">Memory laboratory / names + dates</span><h1>Who said what?</h1><p>Flip every card. Say the name, date, definition and association aloud BEFORE revealing it.</p></div><button class="btn" data-action="start-quiz" data-mode="author">Test author memory →</button></div><div class="panel" style="margin-bottom:17px"><b>Remember the distinctions</b><p><b>Pfleeger</b> = eight SOFTWARE qualities (1987 in notes). <b>Philips</b> = quality and large software (2007). <b>IEEE</b> = systematic, disciplined and technical. <b>Munassan</b> = Specify, Develop, Validate, Evolve (2010). <b>Pressman</b> = Define, Build, Test, Deploy (2010). <b>Ishikawa</b> = cause/effect diagram. <b>NATO</b> = 1968 software crisis.</p><p class="small">The author spellings and quoted formulations are taken from the course study guide. Their exact external publications were not verified.</p></div><div class="author-grid">${authors.map((a,i)=>`<article class="author-card ${authorFlips.has(i)?'flipped':''}" data-action="flip-author" data-index="${i}" role="button" tabindex="0" aria-label="Flip ${html(a.name)} flashcard"><div class="eyebrow">FLASHCARD ${i+1} / ${authors.length}</div><div class="author-name">${html(a.name)}</div><div class="author-year">${html(a.year)}</div><p class="muted">${html(a.association)}</p><div class="reveal"><b>${html(a.concept)}</b><p>${html(a.quote)}</p><p class="small">${html(a.detail)}</p><p class="small">${html(a.note)}</p></div><div class="small" style="color:var(--blue);margin-top:11px">${authorFlips.has(i)?'Tap to hide ↑':'Tap to reveal ↓'}</div></article>`).join('')}</div><div class="section-head"><h2>Instant author drill</h2></div><div class="two-col"><div class="panel"><h3>Recognition</h3><p class="muted">See a definition and identify its author, year or origin.</p><button class="btn soft" data-action="start-quiz" data-mode="author">Start matching →</button></div><div class="panel"><h3>Written recall</h3><p class="muted">Practice full definitions in exam language without seeing the model answer first.</p><button class="btn soft" data-action="start-quiz" data-mode="written">Practise essay recall →</button></div></div>`}
function authorMCQs(){const res=[];for(let i=0;i<authors.length;i++){let a=authors[i],other=authors.filter(x=>x.name!==a.name).map(x=>x.name),options=shuffle([a.name,...shuffle(other).slice(0,3)]);res.push({id:'auth-name-'+i,module:'intro',prompt:`Which author, body or event is associated with “${a.concept}”?`,choices:options,answer:options.indexOf(a.name),explanation:`${a.name} (${a.year}): ${a.concept}. ${a.note}`});let names=shuffle([a.concept,...shuffle(authors.filter(x=>x.name!==a.name).map(x=>x.concept)).slice(0,3)]);res.push({id:'auth-concept-'+i,module:'intro',prompt:`What should you remember about ${a.name} (${a.year})?`,choices:names,answer:names.indexOf(a.concept),explanation:a.quote});}return res}
function renderVault(){let all=[...allMCQ.map(q=>({...q,type:'mcq'})),...allEssay];let arr=all.filter(q=>(vaultFilter==='all'||vaultFilter==='weak'&&getStats(q.id).wrong>0&&getStats(q.id).wrong>=getStats(q.id).right||q.module===vaultFilter)&&(!vaultSearch||[q.prompt,modName(q.module),q.type].join(' ').toLowerCase().includes(vaultSearch.toLowerCase())));return `<div class="title-block"><div><span class="eyebrow">Question vault / all seven topics</span><h1>Everything that can be asked</h1><p>${allMCQ.length} MCQs + ${allEssay.length} written questions. Answers remain hidden until you open each item.</p></div><div class="actions"><a class="btn" href="CSC426_Complete_Question_Bank.pdf" download>↓ Question bank PDF</a><button class="btn secondary" data-action="export-attempts">↓ My attempts CSV</button></div></div><div class="toolbar"><input class="search" id="vaultSearch" value="${html(vaultSearch)}" placeholder="Search questions..." aria-label="Search questions"><div class="actions"><select id="vaultFilter" class="search" style="width:auto;min-width:150px"><option value="all" ${vaultFilter==='all'?'selected':''}>All 7 topics</option><option value="weak" ${vaultFilter==='weak'?'selected':''}>Questions I missed</option>${mods.map(m=>`<option value="${m.id}" ${vaultFilter===m.id?'selected':''}>${html(m.title)}</option>`).join('')}</select></div></div><p class="small" style="margin:0 0 13px">Showing ${arr.length} questions. Every missed question is logged for adaptive revision.</p><div id="vaultResults">${arr.length?arr.map(q=>{const s=getStats(q.id),ans=q.type==='essay'?q.answer:q.choices[q.answer];return `<details class="question-item"><summary><span style="flex:1">${html(q.prompt)}</span> <span class="tag plain">${q.type==='essay'?'Written':'MCQ'}</span> ${s.wrong?`<span class="tag">Missed ${s.wrong}×</span>`:''}</summary><div class="answer"><b>Model answer:</b><p>${html(ans)}</p>${q.explanation?`<p class="small">${html(q.explanation)}</p>`:''}<span class="small">${html(modName(q.module))}</span></div></details>`}).join(''):'<div class="empty">Nothing matches your search or filter.</div>'}</div>`}
function renderPlan(){const n=completeCount();const plan=[['Now','Study the 7 core definitions and Pfleeger/Philips/IEEE.'],['Block 1','Introduction + elicitation. Draw the fishbone from memory.'],['Block 2','Requirement analysis + feasibility: DIPM and TELOS.'],['Block 3','SDLC and models: practise Waterfall, V and Spiral diagrams.'],['Block 4','Development and implementation: data migration and four conversions.'],['Block 5','Testing: levels, techniques, types and V&V.'],['Block 6','Authors and definitions drill. Revisit every missed question.'],['Final block','Take the timed mock exam and revise weakest answers.'],['Before 7 AM','Use your printed question bank for an answer-free final recall.']];return `<div class="title-block"><div><span class="eyebrow">Study strategy / deadline 7:00 AM WAT</span><h1>Tonight’s revision plan</h1><p>Every block is a focus session. Aim to answer without looking, not merely finish reading.</p></div><span class="tag">${n}/${lessons.length} lessons completed</span></div><div class="hero" style="margin-bottom:18px"><div><span class="eyebrow">Study clock</span><h2 style="font-size:25px;margin:8px 0">25 minutes focus + 5 minutes rest</h2><p>Study one chapter segment, answer the recall questions, then take a short break.</p><div class="actions"><button class="btn" data-action="focus-toggle">${focusRunning?'Pause':'Start focus timer'}</button><button class="btn secondary" data-action="focus-reset">Reset timer</button></div></div><div class="countdown"><small>YOUR FOCUS SESSION</small><strong data-focusclock>${formatSeconds(focusSeconds)}</strong><small>Time remaining</small></div></div><div class="plan-grid">${plan.map(([t,x],i)=>`<div class="plan-step"><span class="plan-time">${html(t)}</span><div><b>${i===0?'Baseline recall':i===plan.length-1?'Final memory sweep':'Session '+i}</b><p>${html(x)}</p></div></div>`).join('')}</div><div class="section-head"><h2>Good retention loop</h2></div><div class="panel"><div class="flow">${['Read full definition','Explain example','Close notes','Answer questions','Repeat weak items'].map((s,i)=>`${i?'<span class="flow-arrow">→</span>':''}<div class="flow-step">${s}</div>`).join('')}</div><p class="small">Your progress is saved locally in this browser. Use <b>Export progress</b> to back it up if you switch computers or clear browser data.</p><div class="actions"><button class="btn secondary" data-action="export-progress">↓ Export progress JSON</button><label class="btn secondary" for="importProgress">↑ Import progress JSON</label><input type="file" accept="application/json,.json" id="importProgress" hidden></div></div>`}
function renderMockStart(){if(quiz&&quiz.mode==='mock'&&!quiz.ended)return renderQuiz();return `<div class="title-block"><div><span class="eyebrow">Exam simulation</span><h1>Final mock examination</h1><p>35 multiple-choice questions across all seven chapters. One point per question.</p></div></div><div class="two-col"><div class="panel"><span class="eyebrow">Timed / exam mode</span><h2 style="margin:7px 0">35 questions. 35 minutes.</h2><p class="muted">Answers stay hidden until you finish. You'll receive a score, corrections and a list of weak areas. Retake the exam with new questions.</p><div class="actions"><button class="btn" data-action="start-quiz" data-mode="mock">Begin mock exam →</button></div></div><div class="panel"><span class="eyebrow">Before the exam</span><h3 style="margin-top:7px">Revision checklist</h3><ul class="keylist"><li>Can you reproduce the full definitions?</li><li>Can you name and date the authors?</li><li>Can you draw the main models?</li><li>Can you explain TELOS, DIPM, conversions and testing levels?</li></ul></div></div>`}
function chooseQuestions(mode,mod){let questions;if(mode==='author')questions=authorMCQs();else if(mode==='written')questions=allEssay;else questions=allMCQ;
if(mode==='module')questions=questions.filter(q=>q.module===mod);
if(mode==='weak'){let wrong=questions.filter(q=>getStats(q.id).wrong>0);questions=wrong.length?wrong:questions}
if(mode==='adaptive'||mode==='quick'){questions=shuffle(questions).sort((a,b)=>{let aa=getStats(a.id),bb=getStats(b.id);let pa=(aa.wrong*3-aa.right)+(aa.nextDue<=now()?2:0),pb=(bb.wrong*3-bb.right)+(bb.nextDue<=now()?2:0);return pb-pa+Math.random()-.5})}
if(mode==='mock'){let selected=[];for(const m of mods){let arr=shuffle(questions.filter(q=>q.module===m.id));selected.push(...arr.slice(0,5))}return shuffle(selected)}
return (mode==='adaptive'||mode==='quick'?questions:shuffle(questions)).slice(0,mode==='written'?8:mode==='author'?14:mode==='module'?Math.min(12,questions.length):mode==='quick'?5:10)}
function startQuiz(mode='adaptive',mod=null){const selected=chooseQuestions(mode,mod);if(!selected.length){toast('No questions match that set. Try all-topic practice.');return}quiz={mode,mod,questions:selected,index:0,answers:[],revealed:false,ended:false,endTime:mode==='mock'?now()+35*60000:null,started:now()};quizResult=null;navigate(mode==='mock'?'mock':'quiz')}
function renderQuiz(){if(quizResult&&!quiz)return renderResult();if(!quiz)return `<div class="title-block"><div><span class="eyebrow">Adaptive revision</span><h1>Practice laboratory</h1><p>Practice actively, review mistakes and repeat difficult items over time.</p></div></div><div class="module-grid">${[['adaptive','Adaptive mixed quiz','10 questions, prioritising weak knowledge'],['quick','Quick recall','5 questions for a short memory break'],['author','Author matching','Names, years and definitions'],['written','Written exam practice','Reveal full answers and mark yourself'],['weak','Revisit mistakes','Questions you previously missed'],['mock','Timed mock exam','35 questions, no hints until final score']].map(([id,t,p])=>`<div class="module-card"><h3>${t}</h3><p>${p}</p><button class="btn secondary small" style="align-self:start" data-action="start-quiz" data-mode="${id}">Start →</button></div>`).join('')}</div>`;
if(quiz.ended)return renderResult();const q=quiz.questions[quiz.index],isEssay=q.type==='essay',given=quiz.answers[quiz.index],num=quiz.index+1;return `<div class="quiz-stage"><div class="quiz-head"><span class="tag">${html(quiz.mode.toUpperCase())} · ${html(modName(q.module))}</span><span class="small">Question ${num} of ${quiz.questions.length}</span>${quiz.mode==='mock'?`<span class="timer" data-quiztimer>35:00</span>`:''}</div><div class="quiz-progress"><span style="width:${Math.round((quiz.index)/quiz.questions.length*100)}%"></span></div><div class="panel"><span class="eyebrow">${isEssay?'Write from memory':'Select the best answer'}</span><div class="quiz-question" style="margin-top:11px">${html(q.prompt)}</div>${isEssay?`<textarea id="essayResponse" class="essay-input" placeholder="Write a complete exam answer here without looking...">${html(given?.reply||'')}</textarea><div class="actions"><button class="btn" data-action="reveal-essay">Reveal full model answer</button></div>${quiz.revealed?`<div class="feedback"><b>MODEL ANSWER</b><p>${html(q.answer)}</p><div class="actions" style="margin-top:12px"><button class="btn good" data-action="grade-essay" data-correct="1">I remembered correctly ✓</button><button class="btn secondary" data-action="grade-essay" data-correct="0">Needs more practice ↻</button></div></div>`:''}`:q.choices.map((o,i)=>{let active=quiz.mode==='mock'?false:!!given;return `<button class="option ${active&&i===q.answer?'correct':''} ${active&&given.choice===i&&i!==q.answer?'wrong':''}" data-action="answer-mcq" data-index="${i}" ${given&&quiz.mode!=='mock'?'disabled':''}><span class="letter">${'ABCD'[i]}.</span><span>${html(o)}</span></button>`}).join('')}
${!isEssay&&given&&quiz.mode!=='mock'?`<div class="feedback ${given.correct?'good':'bad'}"><b>${given.correct?'Correct answer.':'Look at the distinction.'}</b><p>${html(q.explanation)}</p></div>`:''}
<div class="hr"></div><div class="quiz-bottom"><span class="small">${quiz.mode==='mock'?'Answers will be shown after submission.':'Keep answering even if you miss a question.'}</span><div class="actions">${quiz.mode==='mock'?`<button class="btn secondary small" data-action="skip-question">Skip</button><button class="btn soft small" data-action="end-quiz">Submit exam</button>`:given?`<button class="btn" data-action="next-question">${num===quiz.questions.length?'See results →':'Next question →'}</button>`:`<button class="btn secondary small" data-action="end-quiz">End session</button>`}</div></div></div></div>`}
function answerMCQ(i){if(!quiz||quiz.ended)return;const q=quiz.questions[quiz.index];if(quiz.answers[quiz.index]&&quiz.mode!=='mock')return;let correct=i===q.answer;quiz.answers[quiz.index]={choice:i,correct};if(quiz.mode==='mock'){if(quiz.index===quiz.questions.length-1)endQuiz();else {quiz.index++;route()}}else{record(q,correct,quiz.mode,q.choices[i]);route()}}
function nextQuestion(){if(!quiz)return;if(quiz.index>=quiz.questions.length-1){endQuiz();return}quiz.index++;quiz.revealed=false;route()}
function skipQuestion(){if(!quiz)return;quiz.answers[quiz.index]={choice:null,correct:false};if(quiz.index===quiz.questions.length-1)endQuiz();else{quiz.index++;route()}}
function revealEssay(){if(!quiz)return;const txt=$('#essayResponse')?.value||'';quiz.answers[quiz.index]={reply:txt,correct:null};quiz.revealed=true;route()}
function gradeEssay(correct){const q=quiz.questions[quiz.index];quiz.answers[quiz.index].correct=!!correct;record(q,!!correct,quiz.mode,quiz.answers[quiz.index].reply);nextQuestion()}
function endQuiz(){if(!quiz)return;const old=quiz;old.ended=true;if(old.mode==='mock')old.questions.forEach((q,i)=>record(q,!!old.answers[i]?.correct,'mock',old.answers[i]?.choice===null?'skipped':q.choices[old.answers[i]?.choice]||'unanswered'));const answered=old.answers.filter(Boolean),correct=answered.filter(a=>a.correct).length;quizResult={mode:old.mode,started:old.started,duration:Math.round((now()-old.started)/1000),total:old.questions.length,answered:answered.length,correct,questions:old.questions,answers:old.answers};quiz=null;store.lastPrompt=now();store.pendingCheck=false;save();navigate('quiz')}
function renderResult(){const r=quizResult,rate=Math.round(r.correct/r.total*100);let wrong=r.questions.map((q,i)=>({q,answer:r.answers[i]})).filter(x=>!x.answer?.correct);return `<div class="quiz-stage"><div class="panel" style="text-align:center;padding:31px"><span class="eyebrow">Session complete · ${html(r.mode)}</span><div class="result-score">${rate}%</div><h2>${r.correct} / ${r.total} correct</h2><p class="muted">${rate>=80?'Strong recall. Work on the remaining mistakes.':rate>=60?'Progress made. Repeat weak material before the next mock.':'Revisit the definitions, then attempt another set.'}</p><div class="actions" style="justify-content:center"><button class="btn" data-action="start-quiz" data-mode="adaptive">Practise again</button><button class="btn secondary" data-action="clear-result">Choose practice mode</button><button class="btn secondary" data-action="navigate" data-target="vault">Review entire bank</button><button class="btn secondary" data-action="export-attempts">Download my mistakes CSV</button></div></div><div class="section-head"><h2>Corrections and explanations</h2><span class="tag">${wrong.length} to review</span></div>${wrong.length?wrong.map(({q,answer})=>`<div class="question-item" style="padding:15px 17px;margin-bottom:10px"><b>${html(q.prompt)}</b><p class="small">${answer?.choice!=null&&q.choices?`Your answer: ${html(q.choices[answer.choice])}`:'Not answered / needs practice'}</p><p><b>Correct answer:</b> ${html(q.type==='essay'?q.answer:q.choices[q.answer])}</p>${q.explanation?`<p class="small">${html(q.explanation)}</p>`:''}</div>`).join(''):'<div class="panel">All answered correctly. Try explaining the answers without looking.</div>'}<div class="actions" style="margin-top:15px"><button class="btn secondary" data-action="navigate" data-target="home">Back to overview</button></div></div>`}
function renderPrompt(){const e=$('#globalPrompt');let due=(now()-(store.lastPrompt||now()))>10*60*1000;const show=!!store.pendingCheck||due;if(!show||quiz){e.hidden=true;return}e.hidden=false;e.innerHTML=`<div><b>🧠 Your recall check is ready.</b> ${store.pendingCheck?'You finished another learning block.':'It has been a while since your last recall.'} Test 5 questions without reopening your notes.</div><div class="actions"><button class="btn small" data-action="quick-quiz">Test me now</button><button class="btn secondary small" data-action="dismiss-prompt">Later</button></div>`}
function completeLesson(){if(!currentLesson)return;const had=store.complete.includes(currentLesson);if(!had){store.complete.push(currentLesson);if(store.complete.length%3===0)store.pendingCheck=true;save()}const idx=lessons.findIndex(l=>l.id===currentLesson);if(idx<lessons.length-1)navigate('lesson/'+lessons[idx+1].id);else navigate('home');toast(had?'Lesson reviewed.':'Lesson marked studied. Progress saved.');renderPrompt()}
function saveNotes(){if(!currentLesson)return;store.notes[currentLesson]=$('#lessonNotes')?.value||'';save();toast('Your explanation has been saved locally.')}
function mini(i,id){const l=lessons.find(x=>x.id===id);if(!l||miniAnswer?.id===id)return;miniAnswer={id,choice:i};record({id:l.id,module:l.module,prompt:l.check.prompt},i===l.check.answer,'lesson',l.check.choices[i]);$('#miniBox').innerHTML=miniOptions(l)}
function speak(part){const l=lessons.find(x=>x.id===currentLesson);if(!l){toast('Open a lesson first.');return}if(!('speechSynthesis'in window)){toast('Speech is unavailable in this browser. Text and visuals still work.');return}speechSynthesis.cancel();let t=part==='academic'?`Full academic definition. ${l.academic}`:part==='visual'?`Visual scenario. ${l.example} Remember: ${l.memory}`:`${l.title}. Full academic definition: ${l.academic}. Plain English: ${l.simple}. Example: ${l.example}. Important points: ${l.keys.join('. ')}. Memory anchor: ${l.memory}`;
const u=new SpeechSynthesisUtterance(t);const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-NG')||voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'))||null;u.lang=u.voice?.lang||'en-GB';u.rate=voiceRate;u.pitch=1;u.onerror=()=>toast('Voice may need an installed browser/system voice.');speechSynthesis.speak(u);toast('Narration started. Use Stop to interrupt.')}
function stopVoice(){if('speechSynthesis'in window)speechSynthesis.cancel()}
function replayVisual(){const l=lessons.find(x=>x.id===currentLesson);if(!l)return;const el=$('#visual-'+l.id);if(!el)return;el.classList.remove('playing');void el.offsetWidth;el.classList.add('playing');setTimeout(()=>el?.classList.remove('playing'),3800)}
function download(filename,mime,content){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
const CSV=v=>{const s=String(v??'');return '"'+(s.match(/^[=+@-]/)?"'":"")+s.replaceAll('"','""')+'"'};
function exportAttempts(){const arr=[['Date/time','Question','Chapter','Correct','Session','Your response'],...store.attempts.map(a=>[a.at,a.question,modName(a.topic),a.correct?'Yes':'No',a.mode,a.reply])];download('CSC426_My_Question_Attempts.csv','text/csv;charset=utf-8','\uFEFF'+arr.map(r=>r.map(CSV).join(',')).join('\r\n'));toast('Attempt log saved as CSV.')}
function exportProgress(){download('CSC426_Progress_Backup.json','application/json',JSON.stringify({version:1,exported:new Date().toISOString(),progress:store},null,2));toast('Progress backup downloaded.')}
async function importProgress(file){try{let data=JSON.parse(await file.text());if(!data.progress||!Array.isArray(data.progress.complete))throw Error('Not a valid CSC426 progress backup');store={...store,...data.progress};save();toast('Progress successfully restored.');route()}catch(e){toast('Import failed: '+e.message)}}
function focusToggle(){focusRunning=!focusRunning;if(focusTimer)clearInterval(focusTimer);if(focusRunning){focusTimer=setInterval(()=>{focusSeconds--;const e=$('[data-focusclock]');if(e)e.textContent=formatSeconds(focusSeconds);if(focusSeconds<=0){focusRunning=false;clearInterval(focusTimer);focusTimer=null;focusSeconds=0;toast('Focus session completed. Take a five-minute break and review what you learned.');store.pendingCheck=true;save();renderPrompt()}},1000)}route()}
function focusReset(){focusRunning=false;if(focusTimer)clearInterval(focusTimer);focusTimer=null;focusSeconds=25*60;route()}
function vaultRefresh(){const e=$('#vaultSearch');const pos=e?.selectionStart??null;$('#view').innerHTML=renderVault();const newEl=$('#vaultSearch');if(newEl){newEl.focus();if(pos!==null)newEl.setSelectionRange(pos,pos)}}
function clickHandler(ev){let el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(a==='navigate')navigate(el.dataset.target);else if(a==='start-quiz')startQuiz(el.dataset.mode,el.dataset.module);else if(a==='quick-quiz'){store.lastPrompt=now();store.pendingCheck=false;save();startQuiz('quick')}else if(a==='answer-mcq')answerMCQ(Number(el.dataset.index));else if(a==='next-question')nextQuestion();else if(a==='clear-result'){quizResult=null;route()}else if(a==='skip-question')skipQuestion();else if(a==='end-quiz')endQuiz();else if(a==='reveal-essay')revealEssay();else if(a==='grade-essay')gradeEssay(el.dataset.correct==='1');else if(a==='mini')mini(Number(el.dataset.index),id);else if(a==='complete-lesson')completeLesson();else if(a==='save-notes')saveNotes();else if(a==='speak')speak(el.dataset.part);else if(a==='stop-voice')stopVoice();else if(a==='flip-author'){let i=Number(el.dataset.index);if(authorFlips.has(i))authorFlips.delete(i);else authorFlips.add(i);const card=el.closest('.author-card');card?.classList.toggle('flipped',authorFlips.has(i))}else if(a==='replay-visual')replayVisual();else if(a==='dismiss-prompt'){store.lastPrompt=now();store.pendingCheck=false;save();renderPrompt()}else if(a==='export-attempts')exportAttempts();else if(a==='export-progress')exportProgress();else if(a==='focus-toggle')focusToggle();else if(a==='focus-reset')focusReset();}
document.addEventListener('click',clickHandler);
document.addEventListener('input',ev=>{if(ev.target.id==='lessonNotes'&&currentLesson){store.notes[currentLesson]=ev.target.value;save()}if(ev.target.id==='vaultSearch'){vaultSearch=ev.target.value;vaultRefresh()}});
document.addEventListener('change',ev=>{if(ev.target.id==='vaultFilter'){vaultFilter=ev.target.value;$('#view').innerHTML=renderVault()}if(ev.target.id==='importProgress'&&ev.target.files?.[0])importProgress(ev.target.files[0])});
document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('.author-card')){ev.preventDefault();ev.target.click()}});
$('#themeToggle').addEventListener('click',()=>{document.documentElement.classList.toggle('dark');try{localStorage.setItem('apexhub_csc426_theme',document.documentElement.classList.contains('dark')?'dark':'light')}catch{}});
$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
try{if(localStorage.getItem('apexhub_csc426_theme')==='dark')document.documentElement.classList.add('dark')}catch{}
window.addEventListener('hashchange',route);save();route();setInterval(()=>{refreshClock();renderPrompt()},30000);
})();
